public str getName()
{
    return fieldPName(InventModelGroupItem, ItemDataAreaId);
}

public Set getAllowedValues()
{
    var                  ret = new Set(Types::String);
    InventModelGroupItem inventModelGroupItem;

    while select inventModelGroupItem
        group by ItemDataAreaId
    {
        if (! ret.in(inventModelGroupItem.ItemDataAreaId))
        {
            ret.add(inventModelGroupItem.ItemDataAreaId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventModelGroupItem, ItemDataAreaId));
    qbr.value(queryValue(_value));
}
